(6989488, 1056003, 108580, '<td valign="top">Funny how many of the blur challenge out takes are ending up in the Feb FS :)<br/>Great image, and has to be blurred to work. It will however battle to compete with the traditional FS.</td>', 'Funny how many of the blur challenge out takes are ending up in the Feb FS :)Great image, and has to be blurred to work. It will however battle to compete with the traditional FS.', '2013-03-02 12:27:10.000000', NULL, 1),
(6989492, 1055769, 108580, '<td valign="top">She''s not singing and she''s p''d off about something that''s for sure. Awesome candid.</td>', 'She''s not singing and she''s p''d off about something that''s for sure. Awesome candid.', '2013-03-02 12:31:19.000000', NULL, 1),
(6989494, 1055705, 108580, '<td valign="top">Great use of UWA F/E. Oddly grainy and it adds grit and rawness.</td>', 'Great use of UWA F/E. Oddly grainy and it adds grit and rawness.', '2013-03-02 12:35:30.000000', NULL, 1),
(6989495, 1054706, 108580, '<td valign="top">Post card perfect. Excellent WB giving a beautiful crisp and un-tainted result.</td>', 'Post card perfect. Excellent WB giving a beautiful crisp and un-tainted result.', '2013-03-02 12:36:27.000000', NULL, 1),
(6989496, 1055645, 108580, '<td valign="top">Another winter scene that is well processed and postcard perfect. To a dweller from the Southern Hemisphere this is as I would expect to see it in winter.</td>', 'Another winter scene that is well processed and postcard perfect. To a dweller from the Southern Hemisphere this is as I would expect to see it in winter.', '2013-03-02 12:37:47.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6989499, 1055827, 108580, '<td valign="top">Another blur shot outtake that ended up in a FS :) Quite pleasing Minso, good B&amp;W. Not liking the tight left of frame against your hand though.</td>', 'Another blur shot outtake that ended up in a FS :) Quite pleasing Minso, good B&W. Not liking the tight left of frame against your hand though.', '2013-03-02 12:39:02.000000', NULL, 1),
(6989500, 1055020, 108580, '<td valign="top">Lovely food shot and great subject, excellent DOF and good lack of annoying shadows. A bit central and lacking some additional contrast.</td>', 'Lovely food shot and great subject, excellent DOF and good lack of annoying shadows. A bit central and lacking some additional contrast.', '2013-03-02 12:40:58.000000', NULL, 1),
(6989504, 1054265, 42256, '<td valign="top">Nice to see you entering on DPC huda! <br/> <br/>Knowing DPC crowd and Free Study challenge voting pattern my guess is this is not getting the love you hoped for, but stay put, this is one of the best websites to learn and improve photography!</td>', 'Nice to see you entering on DPC huda!  Knowing DPC crowd and Free Study challenge voting pattern my guess is this is not getting the love you hoped for, but stay put, this is one of the best websites to learn and improve photography!', '2013-03-02 12:43:45.000000', NULL, 1),
(6989505, 1053796, 108580, '<td valign="top">Wonderful scape, classic foreground feature, slow exposure and deep DOF for the horison. Beautiful. An amazing country NZ. Such diversity and pristine countryside. If only we could get through to our peoples to stop littering and look after the land.</td>', 'Wonderful scape, classic foreground feature, slow exposure and deep DOF for the horison. Beautiful. An amazing country NZ. Such diversity and pristine countryside. If only we could get through to our peoples to stop littering and look after the land.', '2013-03-02 12:45:38.000000', NULL, 1),
(6989507, 1056032, 108580, '<td valign="top">Here we used to call that an Illegal gathering :) The top bird is oddly a different species. Nice sighting and sign of a healthy ecosystem.</td>', 'Here we used to call that an Illegal gathering :) The top bird is oddly a different species. Nice sighting and sign of a healthy ecosystem.', '2013-03-02 12:52:05.000000', NULL, 1),
(6989509, 1055403, 108580, '<td valign="top">Excellent lighting, especially the angle of that lighting. I trust this was UE by perhaps -1.0EV? Lending to the dark background. Excellent pose and composition. Could be a tad sharper and I''m wondering about the missing legs.</td>', 'Excellent lighting, especially the angle of that lighting. I trust this was UE by perhaps -1.0EV? Lending to the dark background. Excellent pose and composition. Could be a tad sharper and I''m wondering about the missing legs.', '2013-03-02 12:54:05.000000', NULL, 1),
(6989510, 1055524, 108580, '<td valign="top">Unusual edifice. Fabulously crisp and angular.</td>', 'Unusual edifice. Fabulously crisp and angular.', '2013-03-02 12:55:01.000000', NULL, 1),
(6989511, 1055226, 108580, '<td valign="top">Wonderful scene with an amazing range of greens despite the snow. A little pocket of mist at the end of the road is quite intriguing. I must say the contrail pollution is saddening. How boldly those Yeti footprints would stand out on their own without the lines in the sky...</td>', 'Wonderful scene with an amazing range of greens despite the snow. A little pocket of mist at the end of the road is quite intriguing. I must say the contrail pollution is saddening. How boldly those Yeti footprints would stand out on their own without the lines in the sky...', '2013-03-02 12:57:27.000000', NULL, 1),
(6989517, 1054173, 69324, '<td valign="top">Nicely processed</td>', 'Nicely processed', '2013-03-02 13:08:52.000000', NULL, 1),
(6989527, 1055750, 108580, '<td valign="top">The cat really is going to slide off but that sad human in the BG makes this image (thanks the title) even more intriguing and beguiling. Jagar-like PP too.</td>', 'The cat really is going to slide off but that sad human in the BG makes this image (thanks the title) even more intriguing and beguiling. Jagar-like PP too.', '2013-03-02 13:36:12.000000', NULL, 1),
