(6995488, 1052908, 19825, '<td valign="top">Nice job. Getting a 6.0+ score in a Free Study is always tougher than regular challenges. Congrats on an excellent emotive portrait and a new personal best. I suspect this is the first of many 6''s.</td>', 'Nice job. Getting a 6.0+ score in a Free Study is always tougher than regular challenges. Congrats on an excellent emotive portrait and a new personal best. I suspect this is the first of many 6''s.', '2013-03-08 15:09:48.000000', NULL, 0),
(6995506, 1055154, 113156, '<td valign="top">My favorite of the challenge, congrats on this wonderful image, makes me want to walk walk walk.</td>', 'My favorite of the challenge, congrats on this wonderful image, makes me want to walk walk walk.', '2013-03-08 16:14:12.000000', NULL, 0),
