(6999607, 1052487, 27812, '<td valign="top">And again I will 10 this, it speaks to me. See, I ''been there. It is a lonely place.</td>', 'And again I will 10 this, it speaks to me. See, I ''been there. It is a lonely place.', '2013-03-14 03:57:01.000000', NULL, 0),
(6999761, 1055746, 3548, '<td valign="top">Do you sometimes feel misunderstood here on this site . . . maybe, in general?<br/>I just reviewed your profile and other work and find it to be quite wonderful. Kind of a surrealistic, abstract impressionism, or some variation thereof. Hoping you get the kind of recognition and appreciation you deserve . . . somewhere/somehow/someway/sometime.<br/>And may your Brown be a badge of honor. Wear it proudly!</td>', 'Do you sometimes feel misunderstood here on this site . . . maybe, in general?I just reviewed your profile and other work and find it to be quite wonderful. Kind of a surrealistic, abstract impressionism, or some variation thereof. Hoping you get the kind of recognition and appreciation you deserve . . . somewhere/somehow/someway/sometime.And may your Brown be a badge of honor. Wear it proudly!', '2013-03-14 11:05:12.000000', NULL, 0),
(6999958, 1056008, 104571, '<td valign="top">:D</td>', ':D', '2013-03-14 15:33:30.000000', NULL, 0),
