INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7010213, 1054265, 117088, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by vikas:</b></div><hr/><i> Nice to see you entering on DPC huda! <br/> <br/>Knowing DPC crowd and Free Study challenge voting pattern my guess is this is not getting the love you hoped for, but stay put, this is one of the best websites to learn and improve photography! </i></td></tr></table> <br/> <br/>Thanks Vikas, I can understand your point here. I am here to gather some valuable feedback on my work. Winning will be nice, but not that important.</td>', 'Originally posted by vikas: Nice to see you entering on DPC huda!  Knowing DPC crowd and Free Study challenge voting pattern my guess is this is not getting the love you hoped for, but stay put, this is one of the best websites to learn and improve photography!   Thanks Vikas, I can understand your point here. I am here to gather some valuable feedback on my work. Winning will be nice, but not that important.', '2013-03-31 15:56:06.000000', NULL, 0),
(7010945, 1055175, 108580, '<td valign="top">Not sure why I missed commenting on this shot Janine. Beautiful timing and pose. Lovely detail on the feathers. White birds are incredibly difficult to shoot with even exposure and no hotspots. I''d say if anything the f/6.3 was too shallow. I''d like to see some crisper focus on the eye at least.</td>', 'Not sure why I missed commenting on this shot Janine. Beautiful timing and pose. Lovely detail on the feathers. White birds are incredibly difficult to shoot with even exposure and no hotspots. I''d say if anything the f/6.3 was too shallow. I''d like to see some crisper focus on the eye at least.', '2013-04-01 07:42:48.000000', NULL, 0),
(7016163, 1055964, 159723, '<td valign="top">What a beautiful image! The whole series !s amazing!</td>', 'What a beautiful image! The whole series !s amazing!', '2013-04-08 09:46:00.000000', NULL, 0),
(7016717, 1055484, 100831, '<td valign="top">the textures make this.</td>', 'the textures make this.', '2013-04-08 23:49:24.000000', NULL, 0),
(7020450, 1055096, 117534, '<td valign="top">Ohhh this is GREAT!!!!! I love stuff like this, and here you could even "grunge" it up more, like the spicify filter in Topaz. I see you said you use Topaz, I''ve got them and NIK, I feel Topaz really adds a lot of structure in their filters, I do use some but I usually make 2 layers, one not topazed, and one done, then when I take them both back into PS, I will lower the opacity of the topaz filter layer until I feel it looks right. <br/> <br/>So your pretty new to DPC also, it''s a GREAT place to learn, put on some tough skin cause you get people commenting on your work, and sometimes they are not so nice... ummm like that littlemav person who said your leading lines was over processed.. LOL <br/> <br/>Jump around and look at some of those how they did it tourtials, there is a wealth of knowledge in the forums!!!</td>', 'Ohhh this is GREAT!!!!! I love stuff like this, and here you could even "grunge" it up more, like the spicify filter in Topaz. I see you said you use Topaz, I''ve got them and NIK, I feel Topaz really adds a lot of structure in their filters, I do use some but I usually make 2 layers, one not topazed, and one done, then when I take them both back into PS, I will lower the opacity of the topaz filter layer until I feel it looks right.  So your pretty new to DPC also, it''s a GREAT place to learn, put on some tough skin cause you get people commenting on your work, and sometimes they are not so nice... ummm like that littlemav person who said your leading lines was over processed.. LOL  Jump around and look at some of those how they did it tourtials, there is a wealth of knowledge in the forums!!!', '2013-04-15 02:43:15.000000', NULL, 0),
(7034971, 1055746, 117474, '<td valign="top">Got the asigmatic for this''un!<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1000203" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1000203.gif'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1000203.gif'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1000203.gif"/></a></td>', 'Got the asigmatic for this''un!', '2013-05-09 14:39:53.000000', NULL, 0),
